import PropTypes from "prop-types";
import React from "react";

import applyReducers from "@traveloka/soya-components/lib/legacy/applyReducers";
import {
  commonRulesMapDisToProps,
  commonRulesReducers,
  commonRulesSelector,
} from "./CommonRuleRedux";
import { compose } from "redux";
import { connect } from "react-redux";
import {
  isLeftConditionValid,
  validateInput,
  getNumberDataTypes,
} from "./CommonRuleFunctions";
import { required, number } from "./ValidationUtil";
import { Button } from "@traveloka/soya-components";
import DropdownInput from "./DropdownInput";
import { NotificationManager } from "@traveloka/soya-components";
import TextInput from "./TextInput";

import * as style from "./CommonRule.styles";

class ConditionLeftModal extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      existingValue:
        props.existingValue === null
          ? this.getDefaultLeftCondition()
          : props.existingValue,
    };
  }

  getDefaultLeftCondition = () => {
    const { operator, ruleStructures } = this.props;
    const expressionStructure = JSON.parse(ruleStructures.expressionStructure);
    const dataTypeStructure = JSON.parse(ruleStructures.dataTypeStructure);
    const formatterStructure = JSON.parse(ruleStructures.formatterStructure);
    const acceptableLeftType = expressionStructure[operator].input[0];
    const compatibleWith = dataTypeStructure[acceptableLeftType]
      ? dataTypeStructure[acceptableLeftType].compatibleWith
      : "";
    for (const i in expressionStructure) {
      if (
        expressionStructure[i].type === "function" ||
        expressionStructure[i].type === "constant"
      ) {
        const leftOutput = expressionStructure[i].output;
        if (this.isLeftFunctionCompatible(leftOutput, compatibleWith)) {
          const result = {};
          for (const j in formatterStructure[i].property) {
            if (j === "BooleanValue") {
              result[j] = true;
            } else {
              result[j] = "";
            }
          }
          result.root = formatterStructure[i].id;
          return result;
        }
      }
    }
  };

  changeDefaultAdditionalField = (root) => {
    const { ruleStructures } = this.props;
    const expressionStructure = JSON.parse(ruleStructures.expressionStructure);
    const formatterStructure = JSON.parse(ruleStructures.formatterStructure);
    const dataTypeStructure = JSON.parse(ruleStructures.dataTypeStructure);
    const result = {};
    for (const i in expressionStructure[root].property) {
      if (
        dataTypeStructure[expressionStructure[root].input[i]].valueOption
          .length > 0
      ) {
        if (
          dataTypeStructure[expressionStructure[root].input[i]]
            .valueOption[0] === "True" ||
          dataTypeStructure[expressionStructure[root].input[i]]
            .valueOption[0] === "False"
        ) {
          result[expressionStructure[root].property[i]] = dataTypeStructure[
            expressionStructure[root].input[i]
          ].valueOption[0].toLowerCase();
        } else {
          result[expressionStructure[root].property[i]] =
            dataTypeStructure[
              expressionStructure[root].input[i]
            ].valueOption[0];
        }
      } else {
        for (const j in formatterStructure[root].fields) {
          if (j === expressionStructure[root].property[i]) {
            result[expressionStructure[root].property[i]] =
              formatterStructure[root].fields[j].defaultValue;
            break;
          }
        }
      }
    }
    return result;
  };

  getModalOptions() {
    const { operator, ruleStructures } = this.props;
    const leftOptions = [];
    const expressionStructure = JSON.parse(ruleStructures.expressionStructure);
    const dataTypeStructure = JSON.parse(ruleStructures.dataTypeStructure);
    const formatterStructure = JSON.parse(ruleStructures.formatterStructure);
    const acceptableLeftType = expressionStructure[operator].input[0];
    const compatibleWith = dataTypeStructure[acceptableLeftType]
      ? dataTypeStructure[acceptableLeftType].compatibleWith
      : "";
    for (const i in expressionStructure) {
      if (
        expressionStructure[i].type === "function" ||
        expressionStructure[i].type === "constant"
      ) {
        const leftOutput = expressionStructure[i].output;
        if (this.isLeftFunctionCompatible(leftOutput, compatibleWith)) {
          leftOptions.push({
            label: formatterStructure[i].label,
            value: formatterStructure[i].id,
          });
        }
      }
    }
    leftOptions.sort((a, b) => {
      if (a.label > b.label) {
        return 1;
      } else if (b.label > a.label) {
        return -1;
      }
      return 0;
    });
    return leftOptions;
  }

  isLeftFunctionCompatible(leftOutput, acceptableLeftType) {
    for (const i in acceptableLeftType) {
      if (acceptableLeftType[i] === leftOutput) {
        return true;
      }
    }
    return false;
  }

  getLeftAdditionalFieldType(left) {
    const { ruleStructures } = this.props;
    const result = {};
    const formatterStructure = JSON.parse(ruleStructures.formatterStructure);
    const dataTypeStructure = JSON.parse(ruleStructures.dataTypeStructure);
    const expressionStructure = JSON.parse(ruleStructures.expressionStructure);

    const property = expressionStructure[left].property;
    const resultFields = [];
    for (const i in property) {
      for (const j in formatterStructure[left].fields) {
        if (property[i] === formatterStructure[left].fields[j].id) {
          const dataType =
            dataTypeStructure[expressionStructure[left].input[i]];
          if (dataType.valueOption.length === 0) {
            const isInputDisabled = formatterStructure[left].fields[j].disabled;
            const defaultValue =
              formatterStructure[left].fields[j].defaultValue;
            if (dataType.type === "String" || dataType.type === "Byte") {
              resultFields.push({
                type: "String",
                label: formatterStructure[left].fields[j].displayAs,
                name: formatterStructure[left].fields[j].id,
                isDisabled: isInputDisabled,
                defaultValue,
              });
            } else if (getNumberDataTypes().includes(dataType.type)) {
              resultFields.push({
                type: "Number",
                label: formatterStructure[left].fields[j].displayAs,
                name: formatterStructure[left].fields[j].id,
                isDisabled: isInputDisabled,
                defaultValue,
                validationFormat: dataType.validationFormat,
              });
            } else {
              resultFields.push({
                type: "Custom",
                label: formatterStructure[left].fields[j].displayAs,
                name: formatterStructure[left].fields[j].id,
                isDisabled: isInputDisabled,
                defaultValue,
                validationFormat: dataType.validationFormat,
              });
            }
          } else {
            resultFields.push({
              type: "Option",
              label: formatterStructure[left].fields[j].displayAs,
              value: dataType.valueOption,
              name: formatterStructure[left].fields[j].id,
            });
          }
        }
      }
    }

    result.fields = resultFields;
    result.info = formatterStructure[left].info;
    return result;
  }

  getDropdownOption(options) {
    const opt = [{ value: undefined, label: "Select", disabled: true }];
    for (const i in options) {
      if (options[i] === "True" || options[i] === "False") {
        opt.push({ value: options[i].toLowerCase(), label: options[i] });
      } else {
        opt.push({ value: options[i], label: options[i] });
      }
    }
    return opt;
  }

  getAdditionalField() {
    const { existingValue } = this.state;
    const additionalFieldToForm = [];
    if (existingValue && existingValue.root) {
      const additionalField = this.getLeftAdditionalFieldType(
        existingValue.root
      );
      for (const i in additionalField.fields) {
        const name = additionalField.fields[i].name;
        additionalFieldToForm.push(
          <div>
            <label key={i + "label"}>{additionalField.fields[i].label}</label>
            <br />
          </div>
        );

        let value = existingValue[name];
        if (
          additionalField.fields[i].type !== "Option" &&
          additionalField.fields[i].defaultValue
        ) {
          value = additionalField.fields[i].defaultValue;
        }

        if (additionalField.fields[i].type === "Number") {
          const validationFormat = !additionalField.fields[i].validationFormat
            ? ".*"
            : additionalField.fields[i].validationFormat;
          additionalFieldToForm.push(
            <TextInput
              key={i + "number"}
              name={name}
              placeholder={name}
              onChange={this.handleChangeAdditionalField}
              validators={[required, number, validateInput]}
              validationFormat={validationFormat}
              value={value}
              isDisabled={additionalField.fields[i].isDisabled}
            />
          );
        } else if (additionalField.fields[i].type === "String") {
          additionalFieldToForm.push(
            <TextInput
              key={i + "string"}
              name={name}
              placeholder={name}
              onChange={this.handleChangeAdditionalField}
              validators={[required]}
              value={value}
              isDisabled={additionalField.fields[i].isDisabled}
            />
          );
        } else if (additionalField.fields[i].type === "Custom") {
          const validationFormat = !additionalField.fields[i].validationFormat
            ? ".*"
            : additionalField.fields[i].validationFormat;
          additionalFieldToForm.push(
            <TextInput
              key={i + "custom"}
              name={name}
              placeholder={name}
              onChange={this.handleChangeAdditionalField}
              validators={[required, validateInput]}
              validationFormat={validationFormat}
              value={value}
              isDisabled={additionalField.fields[i].isDisabled}
            />
          );
        } else if (additionalField.fields[i].type === "Option") {
          additionalFieldToForm.push(
            <DropdownInput
              key={i + "option"}
              name={name}
              onChange={this.handleChangeAdditionalField}
              items={this.getDropdownOption(additionalField.fields[i].value)}
              value={existingValue[name]}
            />
          );
        }
      }
      additionalFieldToForm.push(
        <label key="info">{additionalField.info}</label>
      );
    }
    return additionalFieldToForm;
  }

  handleChangeAdditionalField = (name, value) => {
    const { existingValue } = this.state;
    existingValue[name] = value;
    this.setState({ existingValue });
  };

  handleChangeRoot = (name, value) => {
    const defaultAdditionalField = this.changeDefaultAdditionalField(value);
    const existingValue = Object.assign(defaultAdditionalField);
    existingValue[name] = value;
    this.setState({ existingValue });
  };

  handleCancel = () => {
    const { onCancel } = this.props;
    onCancel();
  };

  handleSave = () => {
    const { onSave } = this.props;
    const { existingValue } = this.state;
    if (isLeftConditionValid(existingValue)) {
      const left = {};
      for (const i in existingValue) {
        left[i] = existingValue[i];
      }
      onSave(left);
    } else {
      NotificationManager.showError({
        message: "Input is not valid, please re-check",
        size: "md",
      });
    }
  };

  render() {
    const value =
      this.state.existingValue && this.state.existingValue.root
        ? this.state.existingValue.root
        : "";
    const items = this.getModalOptions();
    const additionalField = this.getAdditionalField();
    return (
      <div>
        <div>
          <label>{"Condition"}</label>
          <br />
          <DropdownInput
            value={value}
            name="root"
            items={items}
            onChange={this.handleChangeRoot}
          />
        </div>
        <div>{additionalField}</div>
        <div className={style.modalFooter}>
          <Button onClick={this.handleCancel} color="link">
            {"Close"}
          </Button>
          <Button onClick={this.handleSave} color="blue">
            {"OK"}
          </Button>
        </div>
      </div>
    );
  }
}

ConditionLeftModal.propTypes = {
  existingValue: PropTypes.shape({
    root: PropTypes.string,
    value: PropTypes.number,
  }),
  operator: PropTypes.string.isRequired,
  ruleStructures: PropTypes.string.isRequired,
  onCancel: PropTypes.func.isRequired,
  onSave: PropTypes.func.isRequired,
};

const mapStateToProps = (state, ownProps) => ({
  ruleStructures: commonRulesSelector.getRuleStructures(state),
});

export default compose(
  applyReducers(commonRulesReducers),
  connect(mapStateToProps, commonRulesMapDisToProps)
)(ConditionLeftModal);
